use atlas_sqlcipher_proof::Vault;use atlas_faiss_probe::Index;use serde_json::json;use std::fs;
#[test]fn encrypted_snapshot_preserves_full_consistent_workspace(){let dir=std::env::temp_dir().join(format!("atlas-snapshot-proof-{}",uuid::Uuid::new_v4()));fs::create_dir(&dir).unwrap();let source=dir.join("source.db");let dest=dir.join("snapshot.db");let mut v=Vault::create(&source,"snapshot-password").unwrap();let body="UniqueSnapshotBody48917";let title="UniqueSnapshotTitle48917";v.put_note("note",title,body).unwrap();let file=(b"UniqueSnapshotFile48917".repeat(100_000));v.put_file("file","sample.bin",&file[..],None).unwrap();let board=json!({"objects":[{"id":"note","x":13.5,"y":-2},{"id":"file","x":4,"y":5}],"edges":[{"id":"e","from":"note","to":"file"}],"stacks":[]});v.put_board(&board.to_string()).unwrap();v.record_history(json!({"query":"UniqueSnapshotQuery48917","mode":"rag","answer":"UniqueSnapshotAnswer48917"})).unwrap();let mut idx=Index::new().unwrap();let mut vec=[0f32;512];vec[7]=1.;idx.add(&[vec]).unwrap();v.save_index(&idx).unwrap();let history=v.history_entries().unwrap();let mut progress=Vec::new();v.snapshot_to(&dest,"snapshot-password",|done,total|progress.push((done,total))).unwrap();assert!(Vault::open(&dest,"wrong-password").is_err());let copy=Vault::open(&dest,"snapshot-password").unwrap();assert_eq!(copy.get_note("note").unwrap(),body);let mut out=Vec::new();copy.read("file",&mut out).unwrap();assert_eq!(out,file);assert_eq!(serde_json::from_str::<serde_json::Value>(&copy.board().unwrap()).unwrap(),board);assert_eq!(copy.history_entries().unwrap(),history);assert_eq!(copy.load_index().unwrap().reconstruct(0).unwrap(),vec);assert_eq!(v.get_note("note").unwrap(),body);assert_eq!(v.history_entries().unwrap(),history);let prior=fs::read(&dest).unwrap();assert!(v.snapshot_to(&dest,"snapshot-password",|_,_|{}).is_err());assert_eq!(fs::read(&dest).unwrap(),prior);assert_eq!(Vault::open(&dest,"snapshot-password").unwrap().get_note("note").unwrap(),body);drop(copy);drop(v);for entry in fs::read_dir(&dir).unwrap(){let bytes=fs::read(entry.unwrap().path()).unwrap();for text in [title,body,"UniqueSnapshotFile48917","UniqueSnapshotQuery48917","UniqueSnapshotAnswer48917","snapshot-password"]{assert!(!bytes.windows(text.len()).any(|part|part==text.as_bytes()),"plaintext marker {text}");}}fs::remove_dir_all(dir).unwrap();}

#[test]fn damaged_snapshot_fails_to_open_without_affecting_source(){let dir=std::env::temp_dir().join(format!("atlas-snapshot-corrupt-{}",uuid::Uuid::new_v4()));fs::create_dir(&dir).unwrap();let src=dir.join("source");let dst=dir.join("copy");let mut v=Vault::create(&src,"pass").unwrap();v.put_note("id","title","source stays").unwrap();v.snapshot_to(&dst,"pass",|_,_|{}).unwrap();let mut bytes=fs::read(&dst).unwrap();bytes[..64].fill(0);fs::write(&dst,bytes).unwrap();assert!(Vault::open(&dst,"pass").is_err());assert_eq!(v.get_note("id").unwrap(),"source stays");drop(v);fs::remove_dir_all(dir).unwrap();}
#[test]fn snapshot_crash_child(){let Ok(root)=std::env::var("ATLAS_TEST_SNAPSHOT_CRASH") else{return};let dir=std::path::Path::new(&root);let v=Vault::open(&dir.join("source"),"pass").unwrap();let _=v.snapshot_to(&dir.join("staging"),"pass",|_,_|{fs::write(dir.join("ready"),b"ready").unwrap();std::thread::sleep(std::time::Duration::from_secs(30))});}
#[test]fn killed_snapshot_does_not_damage_source_or_publish_final(){use std::{process::{Command,Stdio},time::{Duration,Instant},thread};let dir=std::env::temp_dir().join(format!("atlas-snapshot-kill-{}",uuid::Uuid::new_v4()));fs::create_dir(&dir).unwrap();let mut v=Vault::create(&dir.join("source"),"pass").unwrap();let data=b"CrashUniqueSecret48917".repeat(200_000);v.put("id","title",&data[..]).unwrap();drop(v);let mut child=Command::new(std::env::current_exe().unwrap()).args(["--exact","snapshot_crash_child","--nocapture"]).env("ATLAS_TEST_SNAPSHOT_CRASH",&dir).stdout(Stdio::null()).stderr(Stdio::null()).spawn().unwrap();let end=Instant::now()+Duration::from_secs(10);while !dir.join("ready").exists(){assert!(child.try_wait().unwrap().is_none());assert!(Instant::now()<end);thread::sleep(Duration::from_millis(10))}child.kill().unwrap();child.wait().unwrap();assert!(!dir.join("final").exists());let v=Vault::open(&dir.join("source"),"pass").unwrap();let mut out=vec![];v.read("id",&mut out).unwrap();assert_eq!(out,data);drop(v);for e in fs::read_dir(&dir).unwrap(){let p=e.unwrap().path();if p.is_file(){let bytes=fs::read(p).unwrap();assert!(!bytes.windows(22).any(|x|x==b"CrashUniqueSecret48917"));}}fs::remove_dir_all(dir).unwrap();}
#[test]fn incorrect_reentered_password_never_creates_destination(){let dir=std::env::temp_dir().join(format!("atlas-snapshot-password-{}",uuid::Uuid::new_v4()));fs::create_dir(&dir).unwrap();let src=dir.join("source");let dst=dir.join("copy");let mut v=Vault::create(&src,"correct-password").unwrap();v.put_note("id","title","OriginalPasswordTest48917").unwrap();let before=fs::read(&src).unwrap();assert!(v.snapshot_to(&dst,"wrong-password",|_,_|{}).is_err(),"snapshot accepted incorrect reentered password");assert!(!dst.exists());assert_eq!(v.get_note("id").unwrap(),"OriginalPasswordTest48917");assert_eq!(fs::read(&src).unwrap(),before);drop(v);fs::remove_dir_all(dir).unwrap();}
#[test]fn replaced_source_path_is_refused_without_exposing_password(){let dir=std::env::temp_dir().join(format!("atlas-snapshot-source-swap-{}",uuid::Uuid::new_v4()));fs::create_dir(&dir).unwrap();let src=dir.join("source");let moved=dir.join("original");let dst=dir.join("snapshot");let mut old=Vault::create(&src,"SecretPassword48917").unwrap();old.put_note("id","title","OriginalBody48917").unwrap();fs::rename(&src,&moved).unwrap();let mut replacement=Vault::create(&src,"SecretPassword48917").unwrap();replacement.put_note("id","title","ReplacementBody48917").unwrap();let err=old.snapshot_to(&dst,"SecretPassword48917",|_,_|{}).unwrap_err();assert!(!err.contains("SecretPassword48917")&&!err.contains("OriginalBody48917"));assert!(!dst.exists());assert_eq!(old.get_note("id").unwrap(),"OriginalBody48917");assert_eq!(replacement.get_note("id").unwrap(),"ReplacementBody48917");drop(replacement);drop(old);fs::remove_dir_all(dir).unwrap();}
#[cfg(feature="test-hook")]
#[test]fn no_space_refuses_without_touching_source_or_existing_destination(){let dir=std::env::temp_dir().join(format!("atlas-snapshot-space-{}",uuid::Uuid::new_v4()));fs::create_dir(&dir).unwrap();let src=dir.join("source");let dst=dir.join("copy");let existing=dir.join("existing");let mut v=Vault::create(&src,"pass").unwrap();v.put_note("id","title","OriginalUnique48917").unwrap();fs::write(&existing,b"existing unrelated data").unwrap();let before=fs::read(&src).unwrap();std::env::set_var("ATLAS_TEST_SNAPSHOT_AVAILABLE_BYTES","0");let e=v.snapshot_to(&dst,"pass",|_,_|{}).unwrap_err();assert!(!e.contains("OriginalUnique48917"));assert!(!dst.exists());assert!(v.snapshot_to(&existing,"pass",|_,_|{}).is_err());std::env::remove_var("ATLAS_TEST_SNAPSHOT_AVAILABLE_BYTES");assert_eq!(fs::read(&existing).unwrap(),b"existing unrelated data");assert_eq!(fs::read(&src).unwrap(),before);drop(v);fs::remove_dir_all(dir).unwrap();}
#[test]fn replaced_source_with_modified_byte_copy_is_refused(){let dir=std::env::temp_dir().join(format!("atlas-snapshot-same-salt-{}",uuid::Uuid::new_v4()));fs::create_dir(&dir).unwrap();let src=dir.join("source");let moved=dir.join("original");let dst=dir.join("snapshot");let mut old=Vault::create(&src,"same-password").unwrap();old.put_note("id","title","OriginalBody48917").unwrap();fs::rename(&src,&moved).unwrap();fs::copy(&moved,&src).unwrap();let mut replacement=Vault::open(&src,"same-password").unwrap();replacement.put_note("id","title","ModifiedCopyBody48917").unwrap();drop(replacement);let result=old.snapshot_to(&dst,"same-password",|_,_|{});assert!(result.is_err(),"accepted a changed file copied from original source");assert!(!dst.exists());assert_eq!(old.get_note("id").unwrap(),"OriginalBody48917");drop(old);fs::remove_dir_all(dir).unwrap();}
